package com.example.starter.ili.model;

import java.math.BigDecimal;

/**
 * 单条缺陷读数输入。
 *
 * @param readingKey 客户端读数键，批次+回合内唯一
 * @param stationM   绝对里程，单位米
 * @param depthPct   深度，占壁厚百分比
 */
public record ReadingInput(String readingKey, BigDecimal stationM, BigDecimal depthPct) {
}

package com.example.starter.ili.model;

import java.math.BigDecimal;

/**
 * 匹配引擎输出的一条匹配对。
 *
 * @param oldKey        旧回合读数键
 * @param newKey        新回合读数键
 * @param distanceM     里程差绝对值，单位米
 * @param growthRatePct 深度年增长率，单位 %/年
 * @param grade         系统分级
 */
public record MatchResult(String oldKey, String newKey, BigDecimal distanceM,
                          BigDecimal growthRatePct, Grade grade) {
}

package com.example.starter.ili.model;

import java.util.List;

/**
 * 对齐结果：匹配对、新发现（NEW 侧未匹配读数键）、已消失（OLD 侧未匹配读数键）。
 */
public record AlignmentOutcome(List<MatchResult> matches,
                               List<String> newFindings,
                               List<String> disappeared) {
}

