    private static final RowMapper<BatchRow> MAPPER = (rs, n) -> new BatchRow(
            rs.getLong("id"),
            rs.getString("request_id"),
            rs.getString("segment_id"),
            rs.getString("old_run_id"),
            rs.getString("new_run_id"),
