     * 提交复核结论（仅 OPEN 批次）。
     */
    @PostMapping("/{id}/reviews")
    public BatchView review(@PathVariable long id, @Valid @RequestBody ReviewRequest req) {
        return service.review(id, req);
    }

    /**
     * 封板（终态，重复调用幂等成功）。
